// Arma el mensaje de Discord a partir de la respuesta de /api/reviews/digest.
// Usa embeds (tarjetas): cada uno admite hasta 4.096 caracteres, pero el mensaje completo
// no puede superar los 10 embeds ni los 6.000 caracteres en total.
const d = $input.first().json;
const c = d.byCategory;

const COLORS = { header: 0x5865f2, BUG: 0xed4245, FEATURE_REQUEST: 0xfee75c };
const MAX_TOTAL_CHARS = 5800; // margen debajo del límite de 6.000 de Discord

const header = {
  title: '📊 Goblin Cleanup: weekly review digest',
  color: COLORS.header,
  description: d.total === 0
    ? `No new reviews in the last ${d.days} days.`
    : [
        `**${d.total}** new reviews in the last ${d.days} days · **${d.positivePercent}%** positive`,
        `🐛 Bugs: **${c.BUG}** · 💡 Requests: **${c.FEATURE_REQUEST}** · 👍 Positive: **${c.POSITIVE}** · Other: ${c.OTHER}`,
        ...(d.summary && d.summary.length
          ? ['', d.days === 7 ? '**🤖 This week at a glance**' : `**🤖 Last ${d.days} days at a glance**`, ...d.summary.map((s) => `• ${s}`)]
          : []),
      ].join('\n'),
};

const reviewEmbed = (r, category) => {
  const icon = category === 'BUG' ? '🐛 Bug report' : '💡 Feature request';
  const vote = r.votedUp ? '👍 Recommended' : '👎 Not recommended';
  const text = r.truncated && r.steamUrl ? `${r.text}\n\n[Read the full review on Steam](${r.steamUrl})` : r.text;
  return {
    title: icon,
    url: r.steamUrl || undefined,
    color: COLORS[category],
    description: text || '_(no text)_',
    footer: { text: `${vote} · ${r.playtimeHours} h played` },
    timestamp: r.createdAt,
  };
};

const embeds = [header];
const candidates = [
  ...d.topBugs.map((r) => reviewEmbed(r, 'BUG')),
  ...d.topFeatureRequests.map((r) => reviewEmbed(r, 'FEATURE_REQUEST')),
];

// Agrega reseñas mientras entren en el límite de Discord.
const size = (e) => (e.title || '').length + (e.description || '').length + (e.footer?.text || '').length;
let total = size(header);
for (const e of candidates) {
  if (embeds.length >= 10 || total + size(e) > MAX_TOTAL_CHARS) break;
  embeds.push(e);
  total += size(e);
}

return [{ json: { payload: { embeds } } }];
